+
+  enum class Status {
+    SUCCESS,
+    UNINITIALIZED,
+    UNAVAILABLE,
+    DENIED,
+    ERROR,
+    MAX_VALUE = ERROR
+  };
+
+  class Callback {
+   public:
+    virtual void OnInitialized(Status status) = 0;
+
+   protected:
+    virtual ~Callback() = default;
+  };
