+  assertEq(typeof desc, "object");
+  assertEq(desc.writable, writable);
+  assertEq(desc.enumerable, enumerable);
+  assertEq(desc.configurable, configurable);
+}
+
+function assertThrowsTypeError(thunk) {
+  let error;
+  try {
